from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    counts = Counter()
    for row in grid:
        prev = bg
        for v in row:
            if v != bg and v != prev:
                counts[v] += 1
            prev = v

    values = []
    for color in sorted((c for c in counts if c != bg), reverse=True):
        values.extend([color] * counts[color])
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
